s=s.replace("/// Tool calls whose result the turn banner already reports.","/// Transcript rows one wheel notch moves.\nconst WHEEL_ROWS: usize = 3;\n\n/// Tool calls whose result the turn banner already reports.",1)
s=s.replace("""            KeyCode::Enter => composer.insert("\\n"),
""","""            KeyCode::Enter => composer.insert("\\n"),
            // LF: a newline key every terminal can send, whether or not it reports Shift+Enter.
            KeyCode::Char('j') if ctrl && !alt => composer.insert("\\n"),
""",1)
